<?php $tq = (user() && (int) $q['user_id'] === (int) user()['id']) ? '' : '?t=' . rawurlencode($q['access_token']); ?>
<section class="phead"><div class="wrap"><?= crumbs([['Devis', '/devis'], [$q['ref'], '']]) ?><h1>Devis <?= e($q['ref']) ?></h1><p><?= status_badge(QUOTE_STATUS, $q['status']) ?> · demandé le <?= fdate($q['created_at']) ?></p></div></section>
<div class="wrap two"><div>
  <?php if (get('merci')): ?><div class="alert a-ok"><b>Demande reçue.</b> Conservez ce lien pour suivre votre devis : nous vous répondons rapidement.</div><?php endif; ?>
  <?php if ($lines && in_array($q['status'], ['sent', 'accepted', 'converted', 'declined', 'expired', 'done'], true)): ?>
  <div class="panel"><h2>Votre devis</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Désignation</th><th>Qté</th><th class="right">Prix unitaire</th><th class="right">Total</th></tr></thead><tbody>
    <?php foreach ($lines as $l): ?><tr><td><b><?= e($l['desc']) ?></b><?php if (!empty($l['sub'])): ?><br><small class="muted"><?= e($l['sub']) ?></small><?php endif; ?></td><td><?= (int) $l['qty'] ?></td><td class="right"><?= money($l['unit']) ?></td><td class="right"><?= money($l['qty'] * $l['unit']) ?></td></tr><?php endforeach; ?></tbody></table></div>
    <div class="sl tot"><span>Total</span><span><?= money($q['total']) ?></span></div><?php if ($q['valid_until']): ?><p class="muted"><?= $q['status'] === 'expired' ? 'Ce devis a expiré le ' : "Valable jusqu'au " ?><?= fdate($q['valid_until']) ?>.</p><?php endif; ?><?php if ($q['admin_notes']): ?><div class="hl-box"><?= nl2br(e($q['admin_notes'])) ?></div><?php endif; ?>
    <a class="btn btn-o" href="/devis/<?= e($q['ref']) ?>/pdf<?= $tq ?>" target="_blank"><?= ic('download') ?> Télécharger le PDF</a>
    <?php if ($q['status'] === 'sent'): ?><form method="post" action="/devis/<?= e($q['ref']) ?>/reponse<?= $tq ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="t" value="<?= e($q['access_token']) ?>"><button class="btn btn-a" name="action" value="accept">✓ Accepter le devis</button> <button class="btn btn-g" name="action" value="decline">Refuser</button></form><?php endif; ?>
    <?php if ($q['status'] === 'accepted' && (int) $q['order_id'] <= 0 && feature('quotes.convert')): ?><div class="hl-box" style="margin-top:14px"><b>Devis accepté.</b> Passez commande en quelques clics : vos informations et le montant du devis sont repris.<br><a class="btn btn-a" style="margin-top:8px" href="/devis/<?= e($q['ref']) ?>/commander<?= $tq ?>">Passer commande</a></div><?php endif; ?></div>
  <?php else: ?><div class="panel"><h2>Demande en cours de traitement</h2><p>Un conseiller prépare votre devis chiffré en FCFA. Vous serez prévenu(e) par e-mail dès qu'il est prêt (pensez à vérifier vos courriers indésirables) ; vous pouvez aussi revenir sur cette page avec votre lien.</p></div><?php endif; ?>
  <div class="panel"><h2>Votre demande</h2><?php if (!empty($q['service_type']) && jd($q['details'] ?? '')): ?><ul style="margin:0 0 10px;padding-left:18px"><?php foreach (jd($q['details']) as $d): ?><li><b><?= e($d[0]) ?></b> : <?= e($d[1]) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if (!empty($q['desired_date'])): ?><p><b>Date souhaitée :</b> <?= fdate($q['desired_date']) ?></p><?php endif; ?><?php foreach ($items as $it): ?><p><b><?= e($it['name']) ?></b> × <?= (int) $it['qty'] ?><br><small class="muted"><?= e(implode(' · ', array_map(fn($x) => $x[0] . ' : ' . $x[1], jd($it['summary'])))) ?></small></p><?php endforeach; ?><?php if ($q['message']): ?><p><?= nl2br(e($q['message'])) ?></p><?php endif; ?></div>
  <?php if (feature('quotes.thread')): ?><div class="panel"><h2>Échanges avec notre équipe</h2><?php if (!$thread): ?><p class="muted">Une précision à ajouter ? Écrivez-nous ici : nous vous répondons dans ce fil et par e-mail.</p><?php endif; ?>
    <?php foreach ($thread as $m): ?><div style="margin:0 0 10px;padding:10px 12px;border-radius:10px;background:<?= $m['author'] === 'staff' ? '#e8f4f6' : '#f5f5f5' ?>"><small class="muted"><b><?= $m['author'] === 'staff' ? e(shop('shop_name', 'Symo Print')) : 'Vous' ?></b> · <?= e(fdate($m['created_at'], true)) ?></small><br><?= nl2br(e($m['body'])) ?></div><?php endforeach; ?>
    <form method="post" action="/devis/<?= e($q['ref']) ?>/message<?= $tq ?>"><?= csrf_field() ?><input type="hidden" name="t" value="<?= e($q['access_token']) ?>"><div class="field"><label for="qm">Votre message</label><textarea id="qm" name="body" rows="3" maxlength="2000" required></textarea></div><button class="btn btn-p btn-sm" type="submit">Envoyer</button></form></div><?php endif; ?>
</div><aside class="summary"><h3>Besoin d'aide ?</h3><p class="muted">Nous répondons vite sur WhatsApp.</p><a class="btn btn-p btn-block" href="<?= e(wa_link('Bonjour Symo Print, concernant mon devis ' . $q['ref'] . ' : ')) ?>"><?= ic('wa') ?> WhatsApp</a></aside></div>
